},{"type":"paragraph","content":[{"type":"text","text":"Dört kazancın ikisi hiç eğitim gerektirmedi. Her iyileştirmeyi uygulamadan önce teşhis etmek, rastgele model denemekten çok daha verimli oldu."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Kaynaklar"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"GitHub: "},{"type":"text","text":"trendyol-datathon","marks":[{"type":"link","attrs":{"href":"https://github.com/Beratemek/trendyol-datathon","target":"_blank","rel":"noopener noreferrer nofollow"}}]}]}]}]}]}'::jsonb,
